using System;
using System.Collections;
using System.Collections.Generic;
using System.Threading;
using Cysharp.Threading.Tasks;
using MiniFramework.Contracts;
using MiniFramework.Runtime;
using MiniFramework.Providers.Fake;
using NUnit.Framework;
using UnityEngine.TestTools;
namespace MiniFramework.Package.Tests
{
    public sealed class PackageStartupTests
    {
        static CleanupContext Cleanup=>new CleanupContext(default,Timeout.InfiniteTimeSpan);
        static PackageManifest Good(string version="v1")=>new PackageManifest("main",version,version,"schema",true,new[]{"app"},new[]{"boot","config"});
        static PackageCandidate Candidate(PackageSource source=PackageSource.BuiltIn,string version="v1")=>new PackageCandidate(source,version,"immutable/"+version);
        static PackageProfile Profile(params PackageCandidate[] candidates)=>new PackageProfile("main","app","schema",new[]{"boot","config"},candidates.Length==0?new[]{Candidate()}:candidates);
        sealed class Backend:IPackageBackend
        {
            internal readonly Queue<Session> Sessions=new Queue<Session>(); internal int Creates;internal bool ThrowCreate;
            public IPackageSession Create(PackageProfile p,PackageCandidate c){Creates++;if(ThrowCreate)throw new Exception("create");return Sessions.Dequeue();}
        }
        sealed class Session:IPackageSession
        {
            internal Result<PackageManifest> Result=Result<PackageManifest>.Success(Good());
            internal UniTaskCompletionSource<Result<PackageManifest>> Pending;
            internal UniTaskCompletionSource<Result> PendingCleanup;
            internal Action Preparing;internal int Prepares,Cleans,FailCleans;internal bool ThrowPrepare,ThrowCleanup;
            public UniTask<Result<PackageManifest>> PrepareAsync(){Prepares++;Preparing?.Invoke();if(ThrowPrepare)throw new Exception("prepare");return Pending!=null?Pending.Task:UniTask.FromResult(Result);}
            public UniTask<Result> CleanupAsync(){Cleans++;if(ThrowCleanup)throw new Exception("cleanup");return PendingCleanup!=null?PendingCleanup.Task:UniTask.FromResult(FailCleans-->0?MiniFramework.Contracts.Result.Failure(new FrameworkError(ErrorKind.CleanupFailed,"fake.clean")):MiniFramework.Contracts.Result.Success());}
        }
        sealed class Context:IModuleContext
        {
            internal readonly Scope Owner=new Scope("package-owner"); public IServiceResolver Services=>null;public CancellationToken LifetimeCancellation=>default;public ICleanupRegistry Cleanup=>Owner.Cleanup;
        }
        readonly List<Context> contexts=new List<Context>();readonly List<Session> sessions=new List<Session>();
        PackageStartup New(out Backend backend,out Context context,PackageProfile profile=null,params Session[] values)
        {backend=new Backend();context=new Context();contexts.Add(context);foreach(var s in values){backend.Sessions.Enqueue(s);sessions.Add(s);}return new PackageStartup(profile??Profile(),backend);}
        [UnityTearDown] public IEnumerator TearDown()=>UniTask.ToCoroutine(async()=>{foreach(var s in sessions){s.ThrowCleanup=false;s.FailCleans=0;s.Pending?.TrySetResult(s.Result);s.PendingCleanup?.TrySetResult(Result.Success());}foreach(var c in contexts){await c.Owner.CloseAsync(Cleanup);Assert.IsTrue((await c.Owner.RetryFailedAsync(Cleanup)).IsFullyDrained);}sessions.Clear();contexts.Clear();});
        [UnityTest] public IEnumerator BuiltInCompleteBecomesReady()=>UniTask.ToCoroutine(async()=>{var p=New(out var b,out var c,null,new Session());Assert.IsTrue((await p.InitializeAsync(c,OperationContext.Unlimited())).IsSuccess);Assert.AreEqual(PackageState.Ready,p.State);Assert.AreEqual(PackageSource.BuiltIn,p.SelectedSource);Assert.AreEqual("v1",p.ContentVersion);Assert.IsTrue(p.RetainsSession);});
        [UnityTest] public IEnumerator FirstOfflineWithoutBuiltInFails()=>UniTask.ToCoroutine(async()=>{var s=new Session{Result=Result<PackageManifest>.Failure(new FrameworkError(ErrorKind.Network,"offline"))};var p=New(out var b,out var c,Profile(Candidate(PackageSource.Remote)),s);var result=await p.InitializeAsync(c,OperationContext.Unlimited());Assert.AreEqual(ErrorKind.Network,result.Error.Kind);Assert.AreEqual(PackageState.Failed,p.State);Assert.AreEqual(1,s.Cleans);Assert.IsFalse(p.RetainsSession);});
        [UnityTest] public IEnumerator CachedOfflineUsesCompleteCompatibleVersion()=>UniTask.ToCoroutine(async()=>{var a=new Session{Result=Result<PackageManifest>.Failure(new FrameworkError(ErrorKind.Network,"offline"))};var s=new Session();var p=New(out var b,out var c,Profile(Candidate(PackageSource.Remote),Candidate(PackageSource.CompatibleCache)),a,s);Assert.IsTrue((await p.InitializeAsync(c,OperationContext.Unlimited())).IsSuccess);Assert.AreEqual(PackageSource.CompatibleCache,p.SelectedSource);Assert.AreEqual(1,a.Cleans);Assert.AreEqual(0,s.Cleans);});
        [UnityTest] public IEnumerator CorruptManifestFallsBackAfterCleanup()=>UniTask.ToCoroutine(async()=>{var s=new Session{Result=Result<PackageManifest>.Success(new PackageManifest("main","v1","v1","schema",false,new[]{"app"},new[]{"boot","config"}))};var p=New(out var b,out var c,Profile(Candidate(PackageSource.Remote),Candidate()),s,new Session());Assert.IsTrue((await p.InitializeAsync(c,OperationContext.Unlimited())).IsSuccess);Assert.AreEqual(1,s.Cleans);Assert.AreEqual(PackageSource.BuiltIn,p.SelectedSource);});
        [UnityTest] public IEnumerator CorruptManifestRejected()=>UniTask.ToCoroutine(async()=>{var s=new Session{Result=Result<PackageManifest>.Success(new PackageManifest("main","v1","v1","schema",false,new[]{"app"},new[]{"boot","config"}))};var p=New(out var b,out var c,null,s);Assert.IsFalse((await p.InitializeAsync(c,OperationContext.Unlimited())).IsSuccess);Assert.AreEqual(PackageState.Failed,p.State);Assert.IsNull(p.ContentVersion);Assert.IsFalse(p.RetainsSession);Assert.AreEqual(1,s.Cleans);});
        [UnityTest] public IEnumerator MissingBundleRejected()=>UniTask.ToCoroutine(async()=>{var s=new Session{Result=Result<PackageManifest>.Success(new PackageManifest("main","v1","v1","schema",true,new[]{"app"},new[]{"config"}))};var p=New(out var b,out var c,null,s);Assert.IsFalse((await p.InitializeAsync(c,OperationContext.Unlimited())).IsSuccess);Assert.AreEqual(PackageState.Failed,p.State);Assert.IsNull(p.ContentVersion);Assert.IsFalse(p.RetainsSession);Assert.AreEqual(1,s.Cleans);});
        [UnityTest] public IEnumerator ConfigVersionMismatchRejected()=>UniTask.ToCoroutine(async()=>{var s=new Session{Result=Result<PackageManifest>.Success(new PackageManifest("main","v1","v2","schema",true,new[]{"app"},new[]{"boot","config"}))};var p=New(out var b,out var c,null,s);Assert.IsFalse((await p.InitializeAsync(c,OperationContext.Unlimited())).IsSuccess);Assert.AreEqual(PackageState.Failed,p.State);Assert.IsNull(p.ContentVersion);Assert.IsFalse(p.RetainsSession);Assert.AreEqual(1,s.Cleans);});
        [UnityTest] public IEnumerator SchemaMismatchRejected()=>UniTask.ToCoroutine(async()=>{var s=new Session{Result=Result<PackageManifest>.Success(new PackageManifest("main","v1","v1","other",true,new[]{"app"},new[]{"boot","config"}))};var p=New(out var b,out var c,null,s);Assert.IsFalse((await p.InitializeAsync(c,OperationContext.Unlimited())).IsSuccess);Assert.AreEqual(PackageState.Failed,p.State);Assert.IsNull(p.ContentVersion);Assert.IsFalse(p.RetainsSession);Assert.AreEqual(1,s.Cleans);});
        [UnityTest] public IEnumerator ProgramIncompatibleRejected()=>UniTask.ToCoroutine(async()=>{var s=new Session{Result=Result<PackageManifest>.Success(new PackageManifest("main","v1","v1","schema",true,new[]{"other"},new[]{"boot","config"}))};var p=New(out var b,out var c,null,s);Assert.IsFalse((await p.InitializeAsync(c,OperationContext.Unlimited())).IsSuccess);Assert.AreEqual(PackageState.Failed,p.State);Assert.IsNull(p.ContentVersion);Assert.IsFalse(p.RetainsSession);Assert.AreEqual(1,s.Cleans);});
        [UnityTest] public IEnumerator PackageMismatchRejected()=>UniTask.ToCoroutine(async()=>{var s=new Session{Result=Result<PackageManifest>.Success(new PackageManifest("other","v1","v1","schema",true,new[]{"app"},new[]{"boot","config"}))};var p=New(out var b,out var c,null,s);Assert.IsFalse((await p.InitializeAsync(c,OperationContext.Unlimited())).IsSuccess);Assert.AreEqual(PackageState.Failed,p.State);Assert.IsNull(p.ContentVersion);Assert.IsFalse(p.RetainsSession);Assert.AreEqual(1,s.Cleans);});
        [UnityTest] public IEnumerator ContentVersionMismatchRejected()=>UniTask.ToCoroutine(async()=>{var s=new Session{Result=Result<PackageManifest>.Success(Good("v2"))};var p=New(out var b,out var c,null,s);Assert.IsFalse((await p.InitializeAsync(c,OperationContext.Unlimited())).IsSuccess);Assert.AreEqual(PackageState.Failed,p.State);Assert.IsNull(p.ContentVersion);Assert.IsFalse(p.RetainsSession);Assert.AreEqual(1,s.Cleans);});
        [UnityTest] public IEnumerator NullManifestRejected()=>UniTask.ToCoroutine(async()=>{var s=new Session{Result=Result<PackageManifest>.Success(null)};var p=New(out var b,out var c,null,s);Assert.IsFalse((await p.InitializeAsync(c,OperationContext.Unlimited())).IsSuccess);Assert.AreEqual(PackageState.Failed,p.State);Assert.IsNull(p.ContentVersion);Assert.IsFalse(p.RetainsSession);Assert.AreEqual(1,s.Cleans);});
        [UnityTest] public IEnumerator NotReadyBeforeInitialization()=>UniTask.ToCoroutine(async()=>{var p=New(out var b,out var c);Assert.AreEqual(PackageState.Uninitialized,p.State);Assert.AreEqual(ErrorKind.NotReady,p.CheckReady("main","v1").Error.Kind);Assert.AreEqual(ErrorKind.NotReady,(await p.StartAsync(OperationContext.Unlimited())).Error.Kind);});
        [UnityTest] public IEnumerator ConcurrentWaitsJoinOneActualAttempt()=>UniTask.ToCoroutine(async()=>{var s=new Session{Pending=new UniTaskCompletionSource<Result<PackageManifest>>()};var p=New(out var b,out var c,null,s);var first=p.InitializeAsync(c,OperationContext.Unlimited());var second=p.StartAsync(OperationContext.Unlimited());Assert.AreEqual(PackageState.Initializing,p.State);Assert.AreEqual(ErrorKind.NotReady,p.CheckReady("main","v1").Error.Kind);s.Pending.TrySetResult(s.Result);Assert.IsTrue((await first).IsSuccess);Assert.IsTrue((await second).IsSuccess);Assert.AreEqual(1,b.Creates);});
        [UnityTest] public IEnumerator CanceledObserverDoesNotCancelActualAttempt()=>UniTask.ToCoroutine(async()=>{var s=new Session{Pending=new UniTaskCompletionSource<Result<PackageManifest>>()};var p=New(out var b,out var c,null,s);using(var cancel=new CancellationTokenSource()){var wait=p.InitializeAsync(c,OperationContext.Unlimited(cancel.Token));cancel.Cancel();Assert.AreEqual(ErrorKind.Canceled,(await wait).Error.Kind);Assert.AreEqual(PackageState.Initializing,p.State);s.Pending.TrySetResult(s.Result);Assert.IsTrue((await p.StartAsync(OperationContext.Unlimited())).IsSuccess);}});
        [UnityTest] public IEnumerator TimeoutObserverCanRejoin()=>UniTask.ToCoroutine(async()=>{var s=new Session{Pending=new UniTaskCompletionSource<Result<PackageManifest>>()};var p=New(out var b,out var c,null,s);var first=p.InitializeAsync(c,OperationContext.Unlimited());Assert.AreEqual(ErrorKind.Timeout,(await p.StartAsync(default)).Error.Kind);s.Pending.TrySetResult(s.Result);Assert.IsTrue((await first).IsSuccess);});
        [UnityTest] public IEnumerator LateCompletionAfterStopNeverCommitsReady()=>UniTask.ToCoroutine(async()=>{var s=new Session{Pending=new UniTaskCompletionSource<Result<PackageManifest>>()};var p=New(out var b,out var c,null,s);var first=p.InitializeAsync(c,OperationContext.Unlimited());await p.StopAsync(Cleanup);var close=c.Owner.CloseAsync(Cleanup);Assert.AreEqual(UniTaskStatus.Pending,close.Status);s.Pending.TrySetResult(s.Result);Assert.IsFalse((await first).IsSuccess);Assert.IsTrue((await close).IsFullyDrained);Assert.IsNull(p.ContentVersion);Assert.AreEqual(1,s.Cleans);});
        [UnityTest] public IEnumerator ExplicitRetryCreatesFreshSession()=>UniTask.ToCoroutine(async()=>{var s=new Session{ThrowPrepare=true};var p=New(out var b,out var c,null,s,new Session());Assert.IsFalse((await p.InitializeAsync(c,OperationContext.Unlimited())).IsSuccess);Assert.IsFalse((await p.StartAsync(OperationContext.Unlimited())).IsSuccess);Assert.AreEqual(1,b.Creates);Assert.IsTrue((await p.RetryAsync(OperationContext.Unlimited())).IsSuccess);Assert.AreEqual(2,b.Creates);Assert.AreEqual(1,s.Cleans);});
        [UnityTest] public IEnumerator FailedCleanupBlocksFallbackUntilExplicitRetry()=>UniTask.ToCoroutine(async()=>{var s=new Session{ThrowPrepare=true,FailCleans=1};var p=New(out var b,out var c,Profile(Candidate(),Candidate(PackageSource.CompatibleCache)),s,new Session());Assert.IsFalse((await p.InitializeAsync(c,OperationContext.Unlimited())).IsSuccess);Assert.IsTrue(p.RetainsSession);Assert.AreEqual(1,b.Creates);Assert.IsTrue((await p.RetryAsync(OperationContext.Unlimited())).IsSuccess);Assert.AreEqual(2,s.Cleans);});
        [UnityTest] public IEnumerator PendingCleanupPreventsNextCandidate()=>UniTask.ToCoroutine(async()=>{var s=new Session{ThrowPrepare=true,PendingCleanup=new UniTaskCompletionSource<Result>()};var p=New(out var b,out var c,Profile(Candidate(PackageSource.Remote),Candidate()),s,new Session());var wait=p.InitializeAsync(c,OperationContext.Unlimited());Assert.AreEqual(1,b.Creates);Assert.AreEqual(UniTaskStatus.Pending,wait.Status);s.PendingCleanup.TrySetResult(Result.Success());Assert.IsTrue((await wait).IsSuccess);Assert.AreEqual(2,b.Creates);});
        [UnityTest] public IEnumerator ReadyVersionCannotBeReplaced()=>UniTask.ToCoroutine(async()=>{var p=New(out var b,out var c,null,new Session());await p.InitializeAsync(c,OperationContext.Unlimited());Assert.IsFalse((await p.RetryAsync(OperationContext.Unlimited())).IsSuccess);Assert.IsTrue((await p.StartAsync(OperationContext.Unlimited())).IsSuccess);Assert.AreEqual(1,b.Creates);Assert.AreEqual(ErrorKind.Integrity,p.CheckReady("main","v2").Error.Kind);});
        [UnityTest] public IEnumerator FailedPrepareExceptionStillReleasesSession()=>UniTask.ToCoroutine(async()=>{var s=new Session{ThrowPrepare=true};var p=New(out var b,out var c,null,s);Assert.AreEqual(ErrorKind.Provider,(await p.InitializeAsync(c,OperationContext.Unlimited())).Error.Kind);Assert.AreEqual(1,s.Cleans);});
        [UnityTest] public IEnumerator CreateExceptionClassifiedWithoutOwnedSession()=>UniTask.ToCoroutine(async()=>{var p=New(out var b,out var c);b.ThrowCreate=true;Assert.AreEqual(ErrorKind.Provider,(await p.InitializeAsync(c,OperationContext.Unlimited())).Error.Kind);Assert.IsFalse(p.RetainsSession);});
        [UnityTest] public IEnumerator CloseFailureRetainsAndRegistryRetryReleases()=>UniTask.ToCoroutine(async()=>{var s=new Session{FailCleans=1};var p=New(out var b,out var c,null,s);await p.InitializeAsync(c,OperationContext.Unlimited());Assert.IsFalse((await c.Owner.CloseAsync(Cleanup)).IsFullyDrained);Assert.IsTrue(p.RetainsSession);Assert.IsTrue((await c.Owner.RetryFailedAsync(Cleanup)).IsFullyDrained);Assert.IsFalse(p.RetainsSession);Assert.AreEqual(2,s.Cleans);});
        [UnityTest] public IEnumerator InitializationFailureCleanupIsNotImplicitlyRetried()=>UniTask.ToCoroutine(async()=>{var s=new Session{ThrowPrepare=true,FailCleans=1};var p=New(out var b,out var c,null,s);await p.InitializeAsync(c,OperationContext.Unlimited());Assert.IsFalse((await c.Owner.CloseAsync(Cleanup)).IsFullyDrained);Assert.AreEqual(1,s.Cleans);Assert.IsTrue((await c.Owner.RetryFailedAsync(Cleanup)).IsFullyDrained);Assert.AreEqual(2,s.Cleans);});
        [UnityTest] public IEnumerator CleanupThrowRemainsRetryable()=>UniTask.ToCoroutine(async()=>{var s=new Session{ThrowCleanup=true};var p=New(out var b,out var c,null,s);await p.InitializeAsync(c,OperationContext.Unlimited());Assert.IsFalse((await c.Owner.CloseAsync(Cleanup)).IsFullyDrained);s.ThrowCleanup=false;Assert.IsTrue((await c.Owner.RetryFailedAsync(Cleanup)).IsFullyDrained);});
        [UnityTest] public IEnumerator AssetsDependencyStartsAfterPackageReady()=>UniTask.ToCoroutine(async()=>{var p=New(out var b,out var c,null,new Session());var assets=new AssetsService(new FakeResourceProvider(),"main","v1",Cleanup,packageReadiness:p,packageModuleId:p.Id);var game=new GameContext(new[]{new ModuleRegistration(assets.Id,assets.Dependencies,()=>assets,typeof(IAssetsService)),new ModuleRegistration(p.Id,p.Dependencies,()=>p,typeof(IPackageReadiness))},Cleanup);Assert.IsTrue((await game.StartAsync(OperationContext.Unlimited())).IsSuccess);Assert.IsTrue(p.CheckReady("main","v1").IsSuccess);Assert.IsTrue((await game.CloseAsync(OperationContext.Unlimited())).IsSuccess);Assert.IsFalse(p.RetainsSession);});
        [UnityTest] public IEnumerator AssetsRejectsMismatchedFrozenVersion()=>UniTask.ToCoroutine(async()=>{var p=New(out var b,out var c,null,new Session());await p.InitializeAsync(c,OperationContext.Unlimited());var assets=new AssetsService(new FakeResourceProvider(),"main","v2",Cleanup,packageReadiness:p,packageModuleId:p.Id);Assert.AreEqual(ErrorKind.Integrity,(await assets.InitializeAsync(c,OperationContext.Unlimited())).Error.Kind);});
        [UnityTest] public IEnumerator AssetsRejectsLoadBeforeReady()=>UniTask.ToCoroutine(async()=>{var p=New(out var b,out var c);var assets=new AssetsService(new FakeResourceProvider(),"main","v1",Cleanup,packageReadiness:p,packageModuleId:p.Id);Assert.AreEqual(ErrorKind.NotReady,(await assets.InitializeAsync(c,OperationContext.Unlimited())).Error.Kind);Assert.AreEqual(ErrorKind.NotReady,assets.Load<object>(new ResourceKey("fake","main","v1","boot",typeof(object)),c.Owner).Error.Kind);});
        [UnityTest] public IEnumerator AssetsRejectsNewLoadsAfterPackageStops()=>UniTask.ToCoroutine(async()=>{var p=New(out var b,out var c,null,new Session());await p.InitializeAsync(c,OperationContext.Unlimited());var assets=new AssetsService(new FakeResourceProvider(),"main","v1",Cleanup,packageReadiness:p,packageModuleId:p.Id);await assets.InitializeAsync(c,OperationContext.Unlimited());await p.StopAsync(Cleanup);Assert.AreEqual(ErrorKind.NotReady,assets.Load<object>(new ResourceKey("fake","main","v1","later",typeof(object)),c.Owner).Error.Kind);});
        [UnityTest] public IEnumerator AssetsFreezesFallbackVersionAfterAllFactoriesRun()=>UniTask.ToCoroutine(async()=>{
            var failed=new Session{Result=Result<PackageManifest>.Failure(new FrameworkError(ErrorKind.Network,"offline"))};
            var p=New(out var b,out var c,Profile(Candidate(PackageSource.Remote,"v2"),Candidate(PackageSource.CompatibleCache,"v1")),failed,new Session());
            var assets=new AssetsService(new FakeResourceProvider(),p,Cleanup,p.Id);
            var game=new GameContext(new[]{new ModuleRegistration(assets.Id,assets.Dependencies,()=>assets,typeof(IAssetsService)),new ModuleRegistration(p.Id,p.Dependencies,()=>p,typeof(IPackageReadiness))},Cleanup);
            Assert.IsTrue((await game.StartAsync(OperationContext.Unlimited())).IsSuccess);
            Assert.AreEqual("v1",p.ContentVersion);
            Assert.AreEqual(ErrorKind.InvalidArgument,assets.Load<object>(new ResourceKey("fake","main","v2","boot",typeof(object)),c.Owner).Error.Kind);
            Assert.IsTrue(assets.Load<object>(new ResourceKey("fake","main","v1","boot",typeof(object)),c.Owner).IsSuccess);
            await c.Owner.CloseAsync(Cleanup);Assert.IsTrue((await game.CloseAsync(OperationContext.Unlimited())).IsSuccess);
        });
        [UnityTest] public IEnumerator FailedPackagePreventsDependentModuleInitializationAndRollsBack()=>UniTask.ToCoroutine(async()=>{
            var s=new Session{ThrowPrepare=true};var p=New(out var b,out var c,null,s);var assets=new AssetsService(new FakeResourceProvider(),p,Cleanup,p.Id);
            var game=new GameContext(new[]{new ModuleRegistration(assets.Id,assets.Dependencies,()=>assets,typeof(IAssetsService)),new ModuleRegistration(p.Id,p.Dependencies,()=>p,typeof(IPackageReadiness))},Cleanup);
            Assert.IsFalse((await game.StartAsync(OperationContext.Unlimited())).IsSuccess);Assert.AreEqual(ErrorKind.NotReady,assets.Load<object>(new ResourceKey("fake","main","v1","boot",typeof(object)),c.Owner).Error.Kind);
            Assert.IsTrue((await game.CloseAsync(OperationContext.Unlimited())).IsSuccess);Assert.IsFalse(p.RetainsSession);Assert.AreEqual(1,s.Cleans);
        });
        [UnityTest] public IEnumerator CancellationWinsWhenCompletionArrivesBeforeObserverResumes()=>UniTask.ToCoroutine(async()=>{
            var s=new Session{Pending=new UniTaskCompletionSource<Result<PackageManifest>>()};var p=New(out var b,out var c,null,s);
            using(var cancel=new CancellationTokenSource()){var wait=p.InitializeAsync(c,OperationContext.Unlimited(cancel.Token));cancel.Cancel();s.Pending.TrySetResult(s.Result);Assert.AreEqual(ErrorKind.Canceled,(await wait).Error.Kind);Assert.IsTrue(p.CheckReady("main","v1").IsSuccess);}
        });
        [UnityTest] public IEnumerator SynchronousPreparationCountsTowardObserverDeadline()=>UniTask.ToCoroutine(async()=>{
            var s=new Session{Preparing=()=>Thread.Sleep(10)};var p=New(out var b,out var c,null,s);
            Assert.AreEqual(ErrorKind.Timeout,(await p.InitializeAsync(c,new OperationContext(default,TimeSpan.FromMilliseconds(1)))).Error.Kind);
            Assert.IsTrue(p.CheckReady("main","v1").IsSuccess);
        });
        [Test] public void ProfileCopiesListsAndRejectsEmptyFirstPlay(){var required=new List<string>{"boot"};var candidates=new List<PackageCandidate>{Candidate()};var p=new PackageProfile("main","app","schema",required,candidates);required.Clear();candidates.Clear();Assert.AreEqual(1,p.FirstPlay.Count);Assert.AreEqual(1,p.Candidates.Count);Assert.Throws<ArgumentException>(()=>new PackageProfile("main","app","schema",Array.Empty<string>(),new[]{Candidate()}));}
        [Test] public void AssetsRequiresDeclaredPackageDependency(){Assert.Throws<ArgumentException>(()=>new AssetsService(new FakeResourceProvider(),"main","v1",Cleanup,packageReadiness:new PackageStartup(Profile(),new Backend())));}
    }
}
